import{_ as i,C as n,o as s,c as p,a2 as t,j as r,a,E as l}from"./chunks/framework.CtQGab4e.js";const f=JSON.parse('{"title":"Eigenschappen van vlakken","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/vlakken.md","filePath":"plattegrond/vlakken.md"}'),g={name:"plattegrond/vlakken.md"};function k(h,e,u,m,v,b){const o=n("Icon"),d=n("Media");return s(),p("div",null,[e[4]||(e[4]=t('<h1 id="eigenschappen-van-vlakken" tabindex="-1">Eigenschappen van vlakken <a class="header-anchor" href="#eigenschappen-van-vlakken" aria-label="Permalink to &quot;Eigenschappen van vlakken&quot;">​</a></h1><p>Elke gesloten ring van muren en hulplijnen is een <strong>vlak</strong>: een ruimte (zie <a href="./hoe-de-tool-denkt.html#ruimtes-ontstaan-vanzelf">Hoe de tool denkt</a>). Ontstaat er geen vlak, controleer dan de <a href="./muur-tool.html#scharnieren">scharnieren</a> en de <a href="./../faq.html#ik-tik-in-een-ruimte-maar-er-opent-geen-popup">veelgestelde vragen</a>.</p><h2 id="de-vlak-popup" tabindex="-1">De vlak-popup <a class="header-anchor" href="#de-vlak-popup" aria-label="Permalink to &quot;De vlak-popup&quot;">​</a></h2>',3)),r("p",null,[e[0]||(e[0]=a("Tik met de ",-1)),l(o,{name:"wall"}),e[1]||(e[1]=a()),e[2]||(e[2]=r("strong",null,"Muur",-1)),e[3]||(e[3]=a("-tool in een vlak, zonder dat er een muur geselecteerd is. Er opent een popup met de eigenschappen van die ruimte.",-1))]),l(d,{src:"vlakken-popup.png",width:"430"}),e[5]||(e[5]=t('<h3 id="installaties" tabindex="-1">Installaties <a class="header-anchor" href="#installaties" aria-label="Permalink to &quot;Installaties&quot;">​</a></h3><p>Welke verwarming en koeling deze ruimte heeft. Zie <a href="./installaties.html">Installaties</a>.</p><h3 id="eigenschap" tabindex="-1">Eigenschap <a class="header-anchor" href="#eigenschap" aria-label="Permalink to &quot;Eigenschap&quot;">​</a></h3><p>Wat voor ruimte dit is.</p><table tabindex="0"><thead><tr><th>Eigenschap</th><th>Wanneer</th></tr></thead><tbody><tr><td><strong>Gebruiksoppervlak</strong> (standaard)</td><td>Een gewone ruimte.</td></tr><tr><td><strong>&lt;1,5m</strong></td><td>Het deel van een zolder waar het lager is dan 1,5 m. Wordt gearceerd.</td></tr><tr><td><strong>Niet berekend</strong></td><td>Telt helemaal niet mee, bijvoorbeeld een garage of schuur. De installaties staan dan uit.</td></tr></tbody></table><p class="opmerking">* Het gebruiksoppervlak (Ag) rekent de tool nog niet uit. <strong>&lt;1,5m</strong> verandert daarom alleen de weergave van de tekening, verder doet het niets.</p><h3 id="gebouwdeel" tabindex="-1">Gebouwdeel <a class="header-anchor" href="#gebouwdeel" aria-label="Permalink to &quot;Gebouwdeel&quot;">​</a></h3><p>Bij welk gebouwdeel deze ruimte hoort, bijvoorbeeld <em>Aanbouw</em>. Alleen als er meer dan één <a href="./gebouw.html#gebouwdelen">gebouwdeel</a> is.</p><h3 id="plat-dak" tabindex="-1">Plat dak <a class="header-anchor" href="#plat-dak" aria-label="Permalink to &quot;Plat dak&quot;">​</a></h3><p>Zet onder <strong>Dak en kelder</strong> <strong>Plat dak aanwezig</strong> aan als er boven deze ruimte een plat dak ligt. Daaronder:</p><ul><li><strong>Begrenzing</strong>: waar het dak aan grenst (standaard <em>Buiten</em>).</li><li><strong>Isolatie</strong>: <em>Standaard</em> of een afwijkende isolatie.</li><li><strong>Hoogte</strong>: alleen invullen als het platte dak hoger of lager ligt dan de verdieping.</li></ul><p>Uitleg en voorbeeld: <a href="./../hoe-teken-ik/plat-dak.html">Plat dak</a>.</p><h3 id="kelder" tabindex="-1">Kelder <a class="header-anchor" href="#kelder" aria-label="Permalink to &quot;Kelder&quot;">​</a></h3><p>Met <strong>Kelder eronder</strong> teken je een onverwarmde kelder zonder aparte verdieping. De knop is grijs buiten de begane grond en op een vlak dat <em>Niet berekend</em> is.</p><ol><li>Teken op de begane grond de omtrek van de kelder met hulplijnen, zodat de kelder een eigen vlak is.</li><li>Tik op dat vlak en zet <strong>Kelder eronder</strong> aan.</li><li>Vul de <strong>Kelderhoogte</strong> in. Steekt de kelder boven de vloer uit, vul dan ook <strong>Onder maaiveld</strong> in: hoe ver de onderkant van de kelder onder het maaiveld ligt. Leeg betekent dat de kelder precies onder de vloer zit.</li></ol><p>Een veld wordt rood als de kelder dieper onder het maaiveld ligt dan hij hoog is, of als hij tot aan het plafond komt.</p><p>Steekt de kelder boven de vloer uit, dan haalt de 3D-server die verhoging als hap uit de vloer van de ruimte erboven.</p><p>Rekent de kelder mee in de berekening, of is hij groter dan de begane grond? Teken hem dan als eigen verdieping, zie <a href="./gebouw.html">Gebouweigenschappen</a>.</p>',18))])}const _=i(g,[["render",k]]);export{f as __pageData,_ as default};
